-- Only synthetic people, academic units, and scores; none from the institution.
BEGIN;
-- Explicit SYNTHETIC policy grants, not institutional role defaults.
SELECT '00000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000001',action
FROM unnest(ARRAY['APPROVE_SCHEME','PUBLISH_RESULTS','CORRECT_RESULTS']) AS action;
UPDATE submission_attempts SET sealed_at=now() WHERE id='1a000000-0000-4000-8000-000000000001';
UPDATE submission_attempts SET attempt_state='CHANGES_REQUESTED' WHERE id='1a000000-0000-4000-8000-000000000001';
UPDATE submission_cases SET state='CHANGES_REQUESTED',row_version=3 WHERE id='19000000-0000-4000-8000-000000000001';
UPDATE scheme_versions SET state='APPROVED',approved_by='00000000-0000-4000-8000-000000000004',approved_at=now()
 WHERE id='22000000-0000-4000-8000-000000000001';
UPDATE scheme_versions SET state='ACTIVE' WHERE id='22000000-0000-4000-8000-000000000001';
UPDATE project_reviews SET roster_locked_at=now(),review_state='OPEN',row_version=row_version+1
 WHERE id='26000000-0000-4000-8000-000000000001';
UPDATE assessments SET state='FINALIZED',row_version=row_version+1
 WHERE id='29000000-0000-4000-8000-000000000001';
UPDATE project_reviews SET review_state='FINALIZED',row_version=row_version+1 WHERE id='26000000-0000-4000-8000-000000000001';
UPDATE result_releases SET sealed_at=now() WHERE id='2a000000-0000-4000-8000-000000000001';
UPDATE project_reviews SET review_state='RELEASED',row_version=row_version+1 WHERE id='26000000-0000-4000-8000-000000000001';
COMMIT;
